package com.penny.app.data

import android.content.Context
import androidx.datastore.preferences.core.booleanPreferencesKey
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import kotlinx.coroutines.flow.map

private val Context.pennyDataStore by preferencesDataStore("penny_preferences")

data class PennySettings(
    val onboardingComplete: Boolean = false,
    val notificationsEnabled: Boolean = true,
    val draftTransactionId: String? = null,
    val draftTitle: String = "",
    val draftDescription: String = "",
)

class PennyPreferences(private val context: Context) {
    private object Keys {
        val onboarding = booleanPreferencesKey("onboarding_complete")
        val notifications = booleanPreferencesKey("notifications_enabled")
        val draftId = stringPreferencesKey("draft_id")
        val draftTitle = stringPreferencesKey("draft_title")
        val draftDescription = stringPreferencesKey("draft_description")
    }

    val settings = context.pennyDataStore.data.map { values ->
        PennySettings(
            onboardingComplete = values[Keys.onboarding] ?: false,
            notificationsEnabled = values[Keys.notifications] ?: true,
            draftTransactionId = values[Keys.draftId],
            draftTitle = values[Keys.draftTitle] ?: "",
            draftDescription = values[Keys.draftDescription] ?: "",
        )
    }

    suspend fun completeOnboarding() = context.pennyDataStore.edit { it[Keys.onboarding] = true }
    suspend fun setNotifications(enabled: Boolean) = context.pennyDataStore.edit { it[Keys.notifications] = enabled }
    suspend fun saveDraft(id: String, title: String, description: String) = context.pennyDataStore.edit {
        it[Keys.draftId] = id; it[Keys.draftTitle] = title; it[Keys.draftDescription] = description
    }
    suspend fun clearDraft() = context.pennyDataStore.edit {
        it.remove(Keys.draftId); it.remove(Keys.draftTitle); it.remove(Keys.draftDescription)
    }
    suspend fun clear() = context.pennyDataStore.edit { it.clear() }
}

package com.penny.app.data

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.TypeConverter
import androidx.room.TypeConverters

class PennyConverters {
    @TypeConverter fun direction(value: String) = Direction.valueOf(value)
    @TypeConverter fun direction(value: Direction) = value.name
    @TypeConverter fun kind(value: String) = TransactionKind.valueOf(value)
    @TypeConverter fun kind(value: TransactionKind) = value.name
    @TypeConverter fun source(value: String) = TransactionSource.valueOf(value)
    @TypeConverter fun source(value: TransactionSource) = value.name
}

@Database(entities = [TransactionEntity::class], version = 1, exportSchema = false)
@TypeConverters(PennyConverters::class)
abstract class PennyDatabase : RoomDatabase() {
    abstract fun transactions(): TransactionDao

    companion object {
        fun create(context: Context) = Room.databaseBuilder(
            context.applicationContext,
            PennyDatabase::class.java,
            "penny.db"
        ).build()
    }
}

package com.penny.app.data

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao
interface TransactionDao {
    @Query("SELECT * FROM transactions ORDER BY occurredAt DESC")
    fun observeAll(): Flow<List<TransactionEntity>>

    @Query("SELECT * FROM transactions WHERE id = :id")
    suspend fun byId(id: String): TransactionEntity?

    @Insert(onConflict = OnConflictStrategy.IGNORE)
    suspend fun insert(transaction: TransactionEntity): Long

    @Query("UPDATE transactions SET title = :title, description = :description, updatedAt = :updatedAt WHERE id = :id")
    suspend fun annotate(id: String, title: String, description: String?, updatedAt: Long)

    @Query("UPDATE transactions SET kind = :kind, updatedAt = :updatedAt WHERE id = :id")
    suspend fun updateKind(id: String, kind: TransactionKind, updatedAt: Long)

    @Query("DELETE FROM transactions")
    suspend fun deleteAll()
}

package com.penny.app.sms

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.provider.Telephony
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.ProcessLifecycleOwner
import com.penny.app.BuildConfig
import com.penny.app.PennyApplication
import com.penny.app.data.Direction
import com.penny.app.notifications.ExpenseNotifications
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull

class TransactionSmsReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != Telephony.Sms.Intents.SMS_RECEIVED_ACTION) return
        val pending = goAsync()
        val app = context.applicationContext as PennyApplication
        val messages = Telephony.Sms.Intents.getMessagesFromIntent(intent)
        val body = messages.joinToString("") { it.messageBody.orEmpty() }
        val sender = messages.firstOrNull()?.originatingAddress
        val receivedAt = messages.firstOrNull()?.timestampMillis ?: System.currentTimeMillis()
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            try {
                val transaction = TransactionSmsParser(BuildConfig.DEBUG).parse(sender, body, receivedAt) ?: return@launch
                if (!app.repository.insert(transaction) || transaction.direction != Direction.DEBIT) return@launch
                val foreground = ProcessLifecycleOwner.get().lifecycle.currentState.isAtLeast(Lifecycle.State.STARTED)
                if (foreground) app.foregroundDebitEvents.emit(transaction.id)
                else {
                    val enabled = withTimeoutOrNull(1_000) { app.preferences.settings.first().notificationsEnabled } ?: true
                    if (enabled) ExpenseNotifications.post(context, transaction)
                }
            } finally { pending.finish() }
        }
    }
}

