@Composable
private fun SettingsScreen(
    notificationsEnabled: Boolean,
    onNotifications: (Boolean) -> Unit,
    onRequestPermissions: () -> Unit,
    onDelete: () -> Unit,
    onSimulateDebit: () -> Unit,
    onSimulateCredit: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    val smsGranted = ContextCompat.checkSelfPermission(context, Manifest.permission.RECEIVE_SMS) == PackageManager.PERMISSION_GRANTED
    val notificationGranted = Build.VERSION.SDK_INT < 33 || ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED
    var confirmDelete by remember { mutableStateOf(false) }
    LazyColumn(modifier.fillMaxSize(), contentPadding = PaddingValues(24.dp, 24.dp, 24.dp, 28.dp)) {
        item { Text("Settings", fontSize = 28.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(24.dp)) }
        item { SettingsStatus(Icons.Outlined.Sms, "SMS access", if (smsGranted) "On" else "Off", if (smsGranted) null else "Enable", onRequestPermissions) }
        item {
            SettingsSwitch(Icons.Outlined.NotificationsNone, "Expense notifications", if (!notificationGranted) "Blocked by Android settings" else "Remind me to name new debits", notificationsEnabled && notificationGranted) {
                if (!notificationGranted) onRequestPermissions() else onNotifications(it)
            }
        }
        item { SettingsStatus(Icons.Outlined.Lock, "Privacy", "Your transaction data stays on this device.", null) {} }
        item { SettingsStatus(Icons.Outlined.Info, "About", "Penny 0.1.0 · Personal money tracker", null) {} }
        if (BuildConfig.DEBUG) item {
            Text("Developer tools", fontSize = 13.sp, fontWeight = FontWeight.SemiBold, color = SecondaryText, modifier = Modifier.padding(top = 24.dp, bottom = 8.dp))
            OutlinedButton(onClick = onSimulateDebit, modifier = Modifier.fillMaxWidth()) { Text("Simulate ₹250 debit") }
            OutlinedButton(onClick = onSimulateCredit, modifier = Modifier.fillMaxWidth()) { Text("Simulate ₹5,000 credit") }
        }
        item { TextButton(onClick = { confirmDelete = true }, colors = ButtonDefaults.textButtonColors(contentColor = Error), modifier = Modifier.fillMaxWidth().padding(top = 28.dp)) { Text("Delete all data") } }
    }
    if (confirmDelete) AlertDialog(
        onDismissRequest = { confirmDelete = false }, title = { Text("Delete all data?") },
        text = { Text("This removes every transaction, saved draft, and setting from this device. This cannot be undone.") },
        confirmButton = { TextButton(onClick = { onDelete(); confirmDelete = false }) { Text("Delete", color = Error) } },
        dismissButton = { TextButton(onClick = { confirmDelete = false }) { Text("Cancel") } },
    )
}

