package com.penny.app.sms

import com.penny.app.data.Direction
import com.penny.app.data.TransactionEntity
import com.penny.app.data.TransactionKind
import com.penny.app.data.TransactionSource
import java.math.BigDecimal
import java.math.RoundingMode
import java.security.MessageDigest
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter
import java.util.Locale
import java.util.UUID

class TransactionSmsParser(private val allowSynthetic: Boolean = false) {
    private val amountRegex = Regex(
        "(?i)(?:INR|Rs\\.?|₹)\\s*([0-9][0-9,]*(?:\\.[0-9]{1,2})?)\\s*(?:has\\s+been\\s+)?(?:debited|credited|spent|received)?"
    )
    private val accountRegex = Regex("(?i)(?:a/?c|account)\\s*(?:no\\.?\\s*)?(?:x+|\\*+)?([0-9]{4})")
    private val referenceRegex = Regex("(?i)(?:ref(?:erence)?|txn|utr)\\s*(?:no\\.?|id|#|:)?\\s*([A-Z0-9-]{6,})")
    private val atRegex = Regex("(?i)\\bat\\s+([A-Z][A-Z0-9 &._-]{1,30}?)\\s+(?:on|using|ref|avl|available|$)")
    private val dateRegex = Regex("(?i)(\\d{1,2}-[A-Za-z]{3}-\\d{4})[ ,]+(\\d{1,2}:\\d{2})(?:\\s*(AM|PM))?")

    fun parse(sender: String?, body: String, receivedAt: Long): TransactionEntity? {
        val clean = body.replace(Regex("\\s+"), " ").trim()
        val lower = clean.lowercase(Locale.ROOT)
        if (clean.startsWith("PENNYTEST:") && !allowSynthetic) return null
        if (listOf("otp", "one time password", "declined", "failed", "unsuccessful", "payment request", "requested", "due date", "minimum due", "offer").any(lower::contains)) return null

        val direction = when {
            Regex("(?i)\\b(debited|spent|paid|purchase(?:d)?)\\b").containsMatchIn(clean) -> Direction.DEBIT
            Regex("(?i)\\b(credited|received|deposited)\\b").containsMatchIn(clean) -> Direction.CREDIT
            else -> return null
        }
        val amountMatch = amountRegex.find(clean) ?: return null
        val rupees = runCatching { BigDecimal(amountMatch.groupValues[1].replace(",", "")) }.getOrNull() ?: return null
        val amountMinor = runCatching { rupees.movePointRight(2).setScale(0, RoundingMode.UNNECESSARY).longValueExact() }.getOrNull()
            ?.takeIf { it > 0 } ?: return null
        val account = accountRegex.find(clean)?.groupValues?.get(1)
        val reference = referenceRegex.find(clean)?.groupValues?.get(1)
        val bank = sender?.replace(Regex("(?i)^(?:[A-Z]{2}-)?"), "")?.takeIf { it.any(Char::isLetter) }
            ?.substringBefore('-')?.take(12)?.uppercase(Locale.ROOT)
        val occurred = parseDate(clean) ?: receivedAt
        val normalized = clean.lowercase(Locale.ROOT).replace(Regex("\\s+"), " ")
        val fingerprintBasis = reference?.let { "${direction.name}|${account.orEmpty()}|${it.uppercase()}" }
            ?: "${sender.orEmpty()}|$receivedAt|$normalized"
        val now = System.currentTimeMillis()
        return TransactionEntity(
            id = UUID.randomUUID().toString(),
            amountMinor = amountMinor,
            direction = direction,
            bank = bank,
            accountKey = account?.let { "${bank.orEmpty()}:$it" },
            accountLast4 = account,
            merchantOrSender = atRegex.find(clean)?.groupValues?.get(1)?.trim(),
            occurredAt = occurred,
            receivedAt = receivedAt,
            timeSource = if (occurred == receivedAt) "RECEIVED" else "PARSED_SMS",
            reference = reference,
            kind = if (direction == Direction.DEBIT) TransactionKind.PURCHASE else TransactionKind.CREDIT,
            source = if (clean.startsWith("PENNYTEST:")) TransactionSource.DEBUG_SIMULATION else TransactionSource.SMS,
            fingerprint = sha256(fingerprintBasis),
            createdAt = now,
            updatedAt = now,
        )
    }

    private fun parseDate(body: String): Long? {
        val match = dateRegex.find(body) ?: return null
        return runCatching {
            val pattern = if (match.groupValues[3].isBlank()) "d-MMM-uuuu H:mm" else "d-MMM-uuuu h:mm a"
            val value = listOf(match.groupValues[1], match.groupValues[2], match.groupValues[3])
                .filter(String::isNotBlank).joinToString(" ")
            LocalDateTime.parse(value, DateTimeFormatter.ofPattern(pattern, Locale.ENGLISH))
                .atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()
        }.getOrNull()
    }

    private fun sha256(value: String) = MessageDigest.getInstance("SHA-256")
        .digest(value.toByteArray()).joinToString("") { "%02x".format(it) }
}
package com.penny.app.sms

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.provider.Telephony
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.ProcessLifecycleOwner
import com.penny.app.BuildConfig
import com.penny.app.PennyApplication
import com.penny.app.data.Direction
import com.penny.app.notifications.ExpenseNotifications
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.withTimeoutOrNull

class TransactionSmsReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != Telephony.Sms.Intents.SMS_RECEIVED_ACTION) return
        val pending = goAsync()
        val app = context.applicationContext as PennyApplication
        val messages = Telephony.Sms.Intents.getMessagesFromIntent(intent)
        val body = messages.joinToString("") { it.messageBody.orEmpty() }
        val sender = messages.firstOrNull()?.originatingAddress
        val receivedAt = messages.firstOrNull()?.timestampMillis ?: System.currentTimeMillis()
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            try {
                val transaction = TransactionSmsParser(BuildConfig.DEBUG).parse(sender, body, receivedAt) ?: return@launch
                if (!app.repository.insert(transaction) || transaction.direction != Direction.DEBIT) return@launch
                val foreground = ProcessLifecycleOwner.get().lifecycle.currentState.isAtLeast(Lifecycle.State.STARTED)
                if (foreground) app.foregroundDebitEvents.emit(transaction.id)
                else {
                    val enabled = withTimeoutOrNull(1_000) { app.preferences.settings.first().notificationsEnabled } ?: true
                    if (enabled) ExpenseNotifications.post(context, transaction)
                }
            } finally { pending.finish() }
        }
    }
}

