private fun formatMoney(amountMinor: Long, sign: Boolean = true): String {
    val value = amountMinor / 100.0
    return NumberFormat.getCurrencyInstance(Locale("en", "IN")).apply {
        minimumFractionDigits = if (amountMinor % 100 == 0L) 0 else 2
        maximumFractionDigits = 2
    }.format(value)
}
