@Composable
private fun HomeScreen(
    transactions: List<TransactionEntity>,
    onTransaction: (String) -> Unit,
    onPending: () -> Unit,
    onEnablePermissions: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    val lifecycleOwner = LocalLifecycleOwner.current
    var permissionRefresh by remember { mutableIntStateOf(0) }
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event -> if (event == Lifecycle.Event.ON_RESUME) permissionRefresh++ }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }
    @Suppress("UNUSED_VARIABLE") val refresh = permissionRefresh
    val smsGranted = ContextCompat.checkSelfPermission(context, Manifest.permission.RECEIVE_SMS) == PackageManager.PERMISSION_GRANTED
    val notificationGranted = Build.VERSION.SDK_INT < 33 || ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED
    val zone = ZoneId.systemDefault()
    val today = LocalDate.now(zone)
    val todayItems = transactions.filter { Instant.ofEpochMilli(it.occurredAt).atZone(zone).toLocalDate() == today }
    val (moneyIn, moneyOut) = todayItems.includedTotals()
    val refunds = todayItems.filter { it.kind == TransactionKind.REFUND || it.kind == TransactionKind.REVERSAL }.sumOf { it.amountMinor }
    val spent = moneyOut - refunds
    val pending = transactions.count { it.direction == Direction.DEBIT && it.title.isNullOrBlank() }
    LazyColumn(modifier.fillMaxSize(), contentPadding = PaddingValues(24.dp, 24.dp, 24.dp, 28.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
        item {
            Text("Penny", fontSize = 28.sp, fontWeight = FontWeight.Bold, color = MainText)
            Text(today.format(DateTimeFormatter.ofPattern("EEEE, d MMMM")), fontSize = 14.sp, color = SecondaryText)
        }
        item { SummaryCard(spent, moneyIn, moneyOut) }
        if (!smsGranted) item { PermissionCard("SMS access is off", "New bank alerts cannot be captured.", "Enable", onEnablePermissions) }
        if (!notificationGranted) item { PermissionCard("Expense reminders are off", "Debits will still be saved when SMS access is on.", "Enable", onEnablePermissions) }
        if (pending > 0) item {
            Surface(
                modifier = Modifier.fillMaxWidth().clickable(onClick = onPending), shape = RoundedCornerShape(18.dp),
                border = BorderStroke(1.dp, Border), color = Color.White
            ) {
                Row(Modifier.padding(18.dp), verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Outlined.ReceiptLong, null, tint = PennyPurple)
                    Column(Modifier.weight(1f).padding(horizontal = 14.dp)) {
                        Text(if (pending == 1) "1 expense needs a title" else "$pending expenses need a title", fontWeight = FontWeight.SemiBold)
                        Text("Add titles", color = PennyPurple, fontSize = 14.sp)
                    }
                    Icon(Icons.Outlined.ArrowForward, null, tint = PennyPurple)
                }
            }
        }
        item { Text("Today", fontSize = 18.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(top = 8.dp)) }
        if (todayItems.isEmpty()) item { EmptyState("Your day starts here.", "Transactions will appear when a bank SMS arrives.") }
        else items(todayItems, key = { it.id }) { TransactionRow(it) { onTransaction(it.id) }; HorizontalDivider(color = Border) }
    }
}

