import java.util.Locale

object ExpenseNotifications {
    const val CHANNEL_ID = "expense_reminders"
    const val EXTRA_TRANSACTION_ID = "transaction_id"

    fun createChannel(context: Context) {
        val channel = NotificationChannel(
            CHANNEL_ID, "Expense reminders", NotificationManager.IMPORTANCE_HIGH
        ).apply { description = "Prompts to add a title after a debit SMS" }
        context.getSystemService(NotificationManager::class.java).createNotificationChannel(channel)
    }

    fun post(context: Context, transaction: TransactionEntity) {
        if (Build.VERSION.SDK_INT >= 33 && ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) return
        val intent = Intent(context, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
            putExtra(EXTRA_TRANSACTION_ID, transaction.id)
        }
        val pending = PendingIntent.getActivity(
            context, transaction.id.hashCode(), intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        val amount = NumberFormat.getCurrencyInstance(Locale("en", "IN")).apply { maximumFractionDigits = 0 }
            .format(transaction.amountMinor / 100.0)
        val account = listOfNotNull(transaction.bank, transaction.accountLast4?.let { "••$it" }).joinToString(" ").ifBlank { "Bank transaction" }
        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle("$amount spent. What was it for?")
            .setContentText("$account · Tap to add a title.")
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setAutoCancel(true)
            .setContentIntent(pending)
            .build()
        NotificationManagerCompat.from(context).notify(transaction.id.hashCode(), notification)
    }

    fun cancel(context: Context, id: String) = NotificationManagerCompat.from(context).cancel(id.hashCode())
    fun cancelAll(context: Context) = NotificationManagerCompat.from(context).cancelAll()
}

