@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun HistoryScreen(transactions: List<TransactionEntity>, onTransaction: (String) -> Unit, modifier: Modifier = Modifier) {
    var filter by rememberSaveable { mutableStateOf(HistoryFilter.WEEK) }
    var chosenDateEpochDay by rememberSaveable { mutableStateOf<Long?>(null) }
    var showDatePicker by remember { mutableStateOf(false) }
    val zone = ZoneId.systemDefault(); val today = LocalDate.now(zone)
    val chosenDate = chosenDateEpochDay?.let(LocalDate::ofEpochDay) ?: today
    val from = when (filter) { HistoryFilter.TODAY -> today; HistoryFilter.YESTERDAY -> today.minusDays(1); HistoryFilter.WEEK -> today.minusDays(6); HistoryFilter.CHOOSE -> chosenDate }
    val to = when (filter) { HistoryFilter.YESTERDAY -> today.minusDays(1); HistoryFilter.CHOOSE -> chosenDate; else -> today }
    val filtered = transactions.filter { Instant.ofEpochMilli(it.occurredAt).atZone(zone).toLocalDate() in from..to }
    val (moneyIn, moneyOut) = filtered.includedTotals()
    LazyColumn(modifier.fillMaxSize(), contentPadding = PaddingValues(24.dp, 24.dp, 24.dp, 28.dp)) {
        item { Text("History", fontSize = 28.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(20.dp)) }
        item {
            LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                HistoryFilter.entries.forEach { value ->
                    item(value) {
                        FilterChip(selected = filter == value, onClick = { if (value == HistoryFilter.CHOOSE) showDatePicker = true else filter = value }, label = { Text(when(value) { HistoryFilter.TODAY -> "Today"; HistoryFilter.YESTERDAY -> "Yesterday"; HistoryFilter.WEEK -> "Last 7 days"; HistoryFilter.CHOOSE -> "Choose date" }) })
                    }
                }
            }
            Spacer(Modifier.height(18.dp))
            Text(if (from == to) from.format(DateTimeFormatter.ofPattern("d MMMM uuuu")) else "${from.format(DateTimeFormatter.ofPattern("d MMM"))} – ${to.format(DateTimeFormatter.ofPattern("d MMM uuuu"))}", color = SecondaryText)
            Row(Modifier.padding(vertical = 16.dp)) { SummaryValue("Money in", moneyIn, Credit, Modifier.weight(1f)); SummaryValue("Money out", moneyOut, MainText, Modifier.weight(1f)) }
        }
        if (filtered.isEmpty()) item { EmptyState("No transactions for this period.", "Try another date range.") }
        else {
            val groups = filtered.groupBy { Instant.ofEpochMilli(it.occurredAt).atZone(zone).toLocalDate() }.toSortedMap(reverseOrder())
            groups.forEach { (date, values) ->
                item { Text(if (date == today) "Today" else date.format(DateTimeFormatter.ofPattern("EEEE, d MMMM")), fontSize = 14.sp, fontWeight = FontWeight.SemiBold, modifier = Modifier.padding(top = 18.dp, bottom = 8.dp)) }
                items(values, key = { it.id }) { TransactionRow(it) { onTransaction(it.id) }; HorizontalDivider(color = Border) }
            }
        }
    }
    if (showDatePicker) {
        val pickerState = rememberDatePickerState(
            initialSelectedDateMillis = chosenDate.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli(),
            selectableDates = object : SelectableDates {
                override fun isSelectableDate(utcTimeMillis: Long): Boolean = Instant.ofEpochMilli(utcTimeMillis).atZone(ZoneOffset.UTC).toLocalDate() <= today
            }
        )
        DatePickerDialog(
            onDismissRequest = { showDatePicker = false },
            confirmButton = { TextButton(onClick = {
                pickerState.selectedDateMillis?.let { chosenDateEpochDay = Instant.ofEpochMilli(it).atZone(ZoneOffset.UTC).toLocalDate().toEpochDay(); filter = HistoryFilter.CHOOSE }
                showDatePicker = false
            }) { Text("Choose") } },
            dismissButton = { TextButton(onClick = { showDatePicker = false }) { Text("Cancel") } },
        ) { DatePicker(pickerState) }
    }
}

@Composable
private fun TransactionRow(transaction: TransactionEntity, onClick: () -> Unit) {
    val isCredit = transaction.direction == Direction.CREDIT
    val label = when {
        transaction.kind == TransactionKind.REFUND -> "Refund · ${transaction.title ?: transaction.merchantOrSender ?: "Purchase"}"
        transaction.kind == TransactionKind.OWN_TRANSFER -> "Transfer"
        isCredit -> transaction.merchantOrSender ?: "Money received"
        !transaction.title.isNullOrBlank() -> transaction.title
        else -> "Add a title"
    }
    Row(Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 14.dp), verticalAlignment = Alignment.CenterVertically) {
        Surface(color = if (isCredit) Color(0xFFEDF7F1) else SoftPurple, shape = RoundedCornerShape(14.dp), modifier = Modifier.size(44.dp)) {
            Icon(if (isCredit) Icons.Outlined.SouthWest else Icons.Outlined.NorthEast, null, tint = if (isCredit) Credit else PennyPurple, modifier = Modifier.padding(11.dp))
        }
        Column(Modifier.weight(1f).padding(horizontal = 12.dp)) {
            Text(label ?: "Transaction", fontWeight = FontWeight.Medium, color = if (!isCredit && transaction.title.isNullOrBlank()) PennyPurple else MainText, maxLines = 1, overflow = TextOverflow.Ellipsis)
            val account = listOfNotNull(transaction.bank, transaction.accountLast4?.let { "••$it" }).joinToString(" ").ifBlank { "Bank alert" }
            val time = Instant.ofEpochMilli(transaction.occurredAt).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("h:mm a"))
            Text("$account · $time", fontSize = 12.sp, color = SecondaryText)
        }
        Column(horizontalAlignment = Alignment.End) {
            Text((if (isCredit) "+" else "−") + formatMoney(transaction.amountMinor), fontWeight = FontWeight.SemiBold, color = if (isCredit) Credit else MainText)
            if (transaction.kind == TransactionKind.OWN_TRANSFER) Text("Transfer", fontSize = 11.sp, color = SecondaryText)
            else if (!isCredit && transaction.title.isNullOrBlank()) Text("Pending", fontSize = 11.sp, color = PennyPurple)
        }
    }
}

