            OutlinedButton(onClick = onSimulateCredit, modifier = Modifier.fillMaxWidth()) { Text("Simulate ₹5,000 credit") }
        }
        item { TextButton(onClick = { confirmDelete = true }, colors = ButtonDefaults.textButtonColors(contentColor = Error), modifier = Modifier.fillMaxWidth().padding(top = 28.dp)) { Text("Delete all data") } }
    }
    if (confirmDelete) AlertDialog(
        onDismissRequest = { confirmDelete = false }, title = { Text("Delete all data?") },
        text = { Text("This removes every transaction, saved draft, and setting from this device. This cannot be undone.") },
        confirmButton = { TextButton(onClick = { onDelete(); confirmDelete = false }) { Text("Delete", color = Error) } },
        dismissButton = { TextButton(onClick = { confirmDelete = false }) { Text("Cancel") } },
