            val account = listOfNotNull(transaction.bank, transaction.accountLast4?.let { "••$it" }).joinToString(" ").ifBlank { "Bank alert" }
            val date = Instant.ofEpochMilli(transaction.occurredAt).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("d MMM, h:mm a"))
            Text("$account · $date", color = SecondaryText, fontSize = 14.sp)
            Spacer(Modifier.height(24.dp))
            if (isDebit) {
                Text("What was this for?", fontSize = 20.sp, fontWeight = FontWeight.SemiBold)
                Spacer(Modifier.height(12.dp))
                OutlinedTextField(
                    value = title, onValueChange = { if (it.length <= 60) title = it }, modifier = Modifier.fillMaxWidth(),
                    placeholder = { Text("Food, petrol, groceries…") }, singleLine = true,
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done), keyboardActions = KeyboardActions(onDone = { if (title.isNotBlank()) { saving = true; onSave(title, description) } }),
                    supportingText = { Text("${title.length}/60") }, isError = title.length > 60,
                )
                Row(Modifier.fillMaxWidth().padding(vertical = 10.dp), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    listOf("Food", "Travel", "Shopping", "Other").forEach { chip -> SuggestionChip(onClick = { title = chip }, label = { Text(chip) }) }
                }
                if (!noteExpanded) TextButton(onClick = { noteExpanded = true }) { Text("Add a note") }
                else OutlinedTextField(
                    value = description, onValueChange = { if (it.length <= 300) description = it },
                    label = { Text("Description (optional)") }, modifier = Modifier.fillMaxWidth().heightIn(min = 100.dp), supportingText = { Text("${description.length}/300") }
                )
                Spacer(Modifier.height(12.dp))
                Button(onClick = { saving = true; onSave(title, description) }, enabled = title.isNotBlank() && !saving, modifier = Modifier.fillMaxWidth().heightIn(min = 52.dp), shape = RoundedCornerShape(14.dp)) { Text(if (saving) "Saving…" else "Save expense") }
                TextButton(onClick = onDismiss, modifier = Modifier.fillMaxWidth()) { Text("Later") }
            } else {
                Text(transaction.merchantOrSender ?: "Money received", fontSize = 20.sp, fontWeight = FontWeight.SemiBold)
            }
            if (!transaction.title.isNullOrBlank() || !isDebit) {
                HorizontalDivider(Modifier.padding(vertical = 16.dp), color = Border)
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Checkbox(checked = transaction.kind == TransactionKind.OWN_TRANSFER, onCheckedChange = onTransfer)
                    Text("Transfer between my accounts")
                }
            }
        }
    }
