    val topGlow = if (dark) AuroraViolet.copy(alpha = .24f) else AuroraViolet.copy(alpha = .12f)
    val sideGlow = if (dark) AuroraMagenta.copy(alpha = .13f) else AuroraCyan.copy(alpha = .10f)
