                            unselectedTextColor = MaterialTheme.colorScheme.onSurfaceVariant,
                        ),
                    )
                }
            }
        }
    }
}

@Composable
private fun GlassSnackbarHost(hostState: SnackbarHostState) {
    androidx.compose.material3.SnackbarHost(hostState) { data ->
        Surface(
            modifier = Modifier.padding(16.dp).shadow(22.dp, RoundedCornerShape(22.dp)),
            color = MaterialTheme.colorScheme.inverseSurface.copy(alpha = .94f),
            contentColor = MaterialTheme.colorScheme.inverseOnSurface,
            shape = RoundedCornerShape(22.dp),
        ) {
            Row(Modifier.padding(horizontal = 18.dp, vertical = 15.dp), verticalAlignment = Alignment.CenterVertically) {
                Icon(Icons.Filled.CheckCircle, null, tint = AuroraCyan)
                Text(data.visuals.message, style = MaterialTheme.typography.bodyMedium, modifier = Modifier.weight(1f).padding(start = 12.dp))
                data.visuals.actionLabel?.let { label -> TextButton(onClick = { data.performAction() }) { Text(label) } }
            }
        }
    }
}

@Composable
private fun GlassPanel(contentPadding: PaddingValues = PaddingValues(18.dp), content: @Composable ColumnScope.() -> Unit) {
